export const TOTAL_MEYDAN_COUNT = 95;
export const ANADOLU_TOTAL_COUNT = 37;
export const AVRUPA_TOTAL_COUNT = 58;
export const DOGRUDAN_YONETIM_COUNT = 88;
export const ORTAK_CALISMA_COUNT = 7;

export function getCanonicalMeydanById(id) {
  if (!id) return null;
  const cleanId = String(id).trim().toLowerCase();
  return ALL_CANONICAL_MEYDANLAR.find((m) => m.id.toLowerCase() === cleanId) || null;
}
